import{_ as r,a0 as d,w as a,s,ao as l,I as n,x as e,a1 as o,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"在 Debian Linux 上安裝配置 ISC DHCP 服務器 | LCTT x X-CMD","titleTemplate":false,"description":"在 Debian Linux 上安裝配置 ISC DHCP 服務器 | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Debian Linux 上安裝配置 ISC DHCP 服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Debian Linux 上安裝配置 ISC DHCP 服務器 | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20150410 How to Install and Configure Multihomed ISC DHCP Server on Debian Linux","title":"在 Debian Linux 上安裝配置 ISC DHCP 服務器","tag":"201512","desc":""},"relativePath":"201512/20150410 How to Install and Configure Multihomed ISC DHCP Server on Debian Linux.md","filePath":"[post].md"}'),C={name:"201512/20150410 How to Install and Configure Multihomed ISC DHCP Server on Debian Linux.md"};function D(u,t,m,P,H,w){const p=d("Link");return a(),s("div",null,[t[19]||(t[19]=l(`<h1 id="在-debian-linux-上安裝配置-isc-dhcp-服務器" tabindex="-1">在 Debian Linux 上安裝配置 ISC DHCP 服務器 <a class="header-anchor" href="#在-debian-linux-上安裝配置-isc-dhcp-服務器" aria-label="Permalink to “在 Debian Linux 上安裝配置 ISC DHCP 服務器”">​</a></h1><p>動態主機控制協議（Dynamic Host Control Protocol，DHCP）給網絡管理員提供了一種便捷的方式，為不斷變化的網絡主機或是動態網絡提供網絡層地址。其中最常用的 DHCP 服務工具是 ISC DHCP Server。DHCP 服務的目的是給主機提供必要的網絡信息以便能夠和其他連接在網絡中的主機互相通信。DHCP 服務提供的信息包括：DNS 服務器信息，網絡地址（IP），子網掩碼，默認網關信息，主機名等等。</p><p>本教程介紹運行在 Debian 7.7 上 4.2.4 版的 ISC-DHCP-Server 如何管理多個虛擬局域網（VLAN），也可以非常容易應用到單一網絡上。</p><p>測試用的網絡是通過思科路由器使用傳統的方式來管理 DHCP 租約地址的。目前有 12 個 VLAN 需要通過集中式服務器來管理。把 DHCP 的任務轉移到一個專用的服務器上，路由器可以收回相應的資源，把資源用到更重要的任務上，比如路由尋址，訪問控制列表，流量監測以及網絡地址轉換等。</p><p>另一個將 DHCP 服務轉移到專用服務器的好處，以後會講到，它可以建立動態域名服務器（DDNS），這樣當主機從服務器請求 DHCP 地址的時候，這樣新主機的主機名就會被添加到 DNS 系統裏面。</p><h3 id="安裝和配置-isc-dhcp-服務器" tabindex="-1">安裝和配置 ISC DHCP 服務器### <a class="header-anchor" href="#安裝和配置-isc-dhcp-服務器" aria-label="Permalink to “安裝和配置 ISC DHCP 服務器###”">​</a></h3><p>1、使用 apt 工具用來安裝 Debian 軟件倉庫中的 ISC 軟件，來創建這個多宿主服務器。與其他教程一樣需要使用 root 或者 sudo 訪問權限。請適當的修改，以便使用下面的命令。（LCTT 譯註：下面中括號裏面是註釋，使用的時候請刪除，#表示使用的 root 權限）</p><pre><code># apt-get install isc-dhcp-server 		[安裝 the ISC DHCP Server 軟件]
# dpkg --get-selections isc-dhcp-server		[確認軟件已經成功安裝]
# dpkg -s isc-dhcp-server 			[用另一種方式確認成功安裝]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-ISC-DHCP-Server.jpg" alt="Install ISC DHCP Server in Debian"></p><p>2、 確認服務軟件已經安裝完成，現在需要提供網絡信息來配置服務器，這樣服務器才能夠根據我們的需要來分發網絡信息。作為管理員最起碼需要了解的 DHCP 信息如下：</p><ul><li>網絡地址</li><li>子網掩碼</li><li>動態分配的地址範圍</li></ul><p>其他一些服務器動態分配的有用信息包括：</p><ul><li>默認網關</li><li>DNS 服務器 IP 地址</li><li>域名</li><li>主機名</li><li>網絡廣播地址</li></ul><p>這只是能讓 ISC DHCP 服務器處理的選項中非常少的一部分。如果你想查看所有選項及其描述需要在安裝好軟件後輸入以下命令：</p><pre><code># man dhcpd.conf
</code></pre><p>3、 一旦管理員已經確定了這台服務器分發的所有必要信息，那麼是時候配置服務器並且分配必要的地址池了。在配置任何地址池或服務器配置之前，必須配置 DHCP 服務器偵聽這台服務器上面的一個接口。</p><p>在這台特定的服務器上，設置好網卡後，DHCP 會偵聽名稱名為<code>&#39;bond0&#39;</code>的接口。請適根據你的實際情況來更改服務器以及網絡環境。下面的配置都是針對本教程的。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Configure-ISC-DHCP-Network.jpg" alt="Configure ISC DHCP Network"></p><p>這行指定的是 DHCP 服務偵聽接口（一個或多個）上的 DHCP 流量。修改主配置文件，分配適合的 DHCP 地址池到所需要的網絡上。主配置文件在 /etc/dhcp/dhcpd.conf。用文本編輯器打開這個文件</p><pre><code># nano /etc/dhcp/dhcpd.conf
</code></pre><p>這個配置文件可以配置我們所需要的地址池/主機。文件頂部有 ‘ddns-update-style‘ 這樣一句，在本教程中它設置為 ‘none‘。在以後的教程中會講到動態 DNS，ISC-DHCP-Server 將會與 BIND9 集成，它能夠使主機名更新指向到 IP 地址。</p><p>4、 接下來的部分是管理員配置全局網絡設置，如 DNS 域名，默認的租約時間，IP地址，子網的掩碼，以及其它。如果你想了解所有的選項，請閲讀 man 手冊中的 dhcpd.conf 文件，命令如下：</p><pre><code># man dhcpd.conf
</code></pre><p>對於這台服務器，我們需要在配置文件頂部配置一些全局網絡設置，這樣就不用到每個地址池中去單獨設置了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Configure-ISC-DDNS.png" alt="Configure ISC DDNS"></p><p>我們花一點時間來解釋一下這些選項，在本教程中雖然它們是一些全局設置，但是也可以單獨的為某一個地址池進行配置。</p><ul><li><p>option domain-name “comptech.local”; – 所有使用這台 DHCP 服務器的主機，都將成為 DNS 域 “comptech.local” 的一員</p></li><li><p>option domain-name-servers 172.27.10.6; DHCP 向所有配置這台 DHCP 服務器的的網絡主機分發 DNS 服務器地址為 172.27.10.6</p></li><li><p>option subnet-mask 255.255.255.0; – 每個網絡設備都分配子網掩碼 255.255.255.0 或 /24</p></li><li><p>default-lease-time 3600; – 默認有效的地址租約時間（單位是秒）。如果租約時間耗盡，那麼主機可以重新申請租約。如果租約完成，那麼相應的地址也將被儘快回收。</p></li><li><p>max-lease-time 86400; – 這是一台主機所能租用的最大的租約時間（單位為秒）。</p></li><li><p>ping-check true; – 這是一個額外的測試，以確保服務器分發出的網絡地址不是當前網絡中另一台主機已使用的網絡地址。</p></li><li><p>ping-timeout; – 在判斷地址以前沒有使用過前，服務器將等待 ping 響應多少秒。</p></li><li><p>ignore client-updates; 現在這個選項是可以忽略的，因為 DDNS 在前面已在配置文件中已經被禁用，但是當 DDNS 運行時，這個選項會忽略主機更新其 DNS 主機名的請求。</p></li></ul><p>5、 文件中下面一行是權威 DHCP 所在行。這行的意義是如果服務器是為文件中所配置的網絡分發地址的服務器，那麼取消對該權威關鍵字(authoritative stanza) 的註釋。</p><p>通過去掉關鍵字 authoritative 前面的 ‘#’，取消註釋全局權威關鍵字。這台服務器將是它所管理網絡裏面的唯一權威。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/ISC-authoritative.png" alt="Enable ISC Authoritative"></p><p>默認情況下服務器被假定為<strong>不是</strong>網絡上的權威服務器。之所以這樣做是出於安全考慮。如果有人因為不瞭解 DHCP 服務的配置，導致配置不當或配置到一個不該出現的網絡裏面，這都將帶來非常嚴重的連接問題。這行還可用在每個網絡中單獨配置使用。也就是説如果這台服務器不是整個網絡的 DHCP 服務器，authoritative 行可以用在每個單獨的網絡中，而不是像上面截圖中那樣的全局配置。</p><p>6、 這一步是配置服務器將要管理的所有 DHCP 地址池/網絡。簡短起見，本教程只講到配置的地址池之一。作為管理員需要收集一些必要的網絡信息（比如域名，網絡地址，有多少地址能夠被分發等等）</p><p>以下這個地址池所用到的信息都是管理員收集整理的：網絡 ID 172.27.60.0, 子網掩碼 255.255.255.0 或 /24, 默認子網網關 172.27.60.1，廣播地址 172.27.60.255.0 。</p><p>以上這些信息對於構建 dhcpd.conf 文件中新網絡非常重要。使用文本編輯器修改配置文件添加新網絡進去，這裏我們需要使用 root 或 sudo 訪問權限。</p><pre><code># nano /etc/dhcp/dhcpd.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/ISC-network.png" alt="Configure DHCP Pools and Networks"></p><p>當前這個例子是給用 VMWare 創建的虛擬服務器分配 IP 地址。第一行顯示是該網絡的子網掩碼。括號裏面的內容是 DHCP 服務器應該提供給網絡上面主機的所有選項。</p><p>第一行， range 172.27.60.50 172.27.60.254; 這一行顯示的是，DHCP 服務在這個網絡上能夠給主機動態分發的地址範圍。</p><p>第二行，option routers 172.27.60.1; 這裏顯示的是給網絡裏面所有的主機分發的默認網關地址。</p><p>最後一行， option broadcast-address 172.27.60.255; 顯示當前網絡的廣播地址。這個地址不能被包含在要分發放的地址範圍內，因為廣播地址不能分配到一個主機上面。</p><p>必須要強調的是每行的結尾必須要用（;）來結束，所有創建的網絡必須要在 {} 裏面。</p><p>7、 如果要創建多個網絡，繼續創建完它們的相應選項後保存文本文件即可。配置完成以後如果有更改，ISC-DHCP-Server 進程需要重啓來使新的更改生效。重啓進程可以通過下面的命令來完成：</p><pre><code># service isc-dhcp-server restart
</code></pre>`,43)),n("p",null,[t[1]||(t[1]=e("這條命令將重啓 DHCP 服務，管理員能夠使用幾種不同的方式來檢查服務器是否已經可以處理 dhcp 請求。最簡單的方法是通過 ",-1)),o(p,{href:"http://www.tecmint.com/10-lsof-command-examples-in-linux/"},{default:i(()=>[...t[0]||(t[0]=[e("lsof 命令",-1)])]),_:1}),t[2]||(t[2]=e("來查看服務器是否在偵聽67端口，命令如下：",-1))]),t[20]||(t[20]=n("pre",null,[n("code",null,`# lsof -i :67
`)],-1)),t[21]||(t[21]=n("p",null,[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/04/lsof.png",alt:"Check DHCP Listening Port"})],-1)),t[22]||(t[22]=n("p",null,"這裏輸出的結果表明 dhcpd（DHCP 服務守護進程）正在運行並且偵聽67端口。由於在 /etc/services 文件中67端口的映射，所以輸出中的67端口實際上被轉換成了 “bootps”。",-1)),t[23]||(t[23]=n("p",null,"在大多數的系統中這是非常常見的，現在服務器應該已經為網絡連接做好準備，我們可以將一台主機接入網絡請求DHCP地址來驗證服務是否正常。",-1)),t[24]||(t[24]=n("h3",{id:"測試客户端連接",tabindex:"-1"},[e("測試客户端連接 "),n("a",{class:"header-anchor",href:"#測試客户端連接","aria-label":"Permalink to “測試客户端連接”"},"​")],-1)),t[25]||(t[25]=n("p",null,"8、 現在許多系統使用網絡管理器來維護網絡連接狀態，因此這個設備應該預先配置好的，只要對應的接口處於活躍狀態就能夠獲取 DHCP。",-1)),t[26]||(t[26]=n("p",null,"然而當一台設備無法使用網絡管理器時，它可能需要手動獲取 DHCP 地址。下面的幾步將演示怎樣手動獲取以及如何查看服務器是否已經按需要分發地址。",-1)),n("p",null,[t[4]||(t[4]=e("‘",-1)),o(p,{href:"http://www.tecmint.com/ifconfig-command-examples/"},{default:i(()=>[...t[3]||(t[3]=[e("ifconfig",-1)])]),_:1}),t[5]||(t[5]=e("‘工具能夠用來檢查接口的配置。這台被用來測試的 DHCP 服務器的設備，它只有一個網絡適配器（網卡），這塊網卡被命名為 ‘eth0‘。",-1))]),t[27]||(t[27]=l(`<pre><code># ifconfig eth0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/No-ip.png" alt="Check Network Interface IP Address"></p><p>從輸出結果上看，這台設備目前沒有 IPv4 地址，這樣很便於測試。我們把這台設備連接到 DHCP 服務器併發出一個請求。這台設備上已經安裝了一個名為 ‘dhclient‘ 的DHCP客户端工具。因為操作系統各不相同，所以這個客户端軟件也是互不一樣的。</p><pre><code># dhclient eth0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/IP.png" alt="Request IP Address from DHCP"></p><p>當前 <code>&#39;inet addr:&#39;</code> 字段中顯示了屬於 172.27.60.0 網絡地址範圍內的 IPv4 地址。值得欣慰的是當前網絡還配置了正確的子網掩碼並且分發了廣播地址。</p><p>到這裏看起來還都不錯，讓我們來測試一下，看看這台設備收到新 IP 地址是不是由服務器發出的。這裏我們參照服務器的日誌文件來完成這個任務。雖然這個日誌的內容有幾十萬條，但是裏面只有幾條是用來確定服務器是否正常工作的。這裏我們使用一個工具 ‘tail’，它只顯示日誌文件的最後幾行，這樣我們就可以不用拿一個文本編輯器去查看所有的日誌文件了。命令如下：</p><pre><code># tail /var/log/syslog
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/DHCP-Log.png" alt="Check DHCP Logs"></p><p>OK!服務器記錄表明它分發了一個地址給這台主機 (HRTDEBXENSRV)。服務器按預期運行，給它充當權威服務器的網絡分發了適合的網絡地址。至此 DHCP 服務器搭建成功並且運行。如果有需要你可以繼續配置其他的網絡，排查故障，確保安全。</p><p>在以後的Debian教程中我會講一些新的 ISC-DHCP-Server 功能。有時間的話我將寫一篇關於 Bind9 和 DDNS 的教程，融入到這篇文章裏面。</p><hr>`,12)),n("p",null,[t[7]||(t[7]=e("via: ",-1)),o(p,{href:"http://www.tecmint.com/install-and-configure-multihomed-isc-dhcp-server-on-debian-linux/"},{default:i(()=>[...t[6]||(t[6]=[e("http://www.tecmint.com/install-and-configure-multihomed-isc-dhcp-server-on-debian-linux/",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=e("作者：",-1)),o(p,{href:"http://www.tecmint.com/author/robturner/"},{default:i(()=>[...t[8]||(t[8]=[e("Rob Turner",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),o(p,{href:"https://github.com/ivo-wang"},{default:i(()=>[...t[9]||(t[9]=[e("ivo-wang",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:i(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創翻譯，",-1)),o(p,{href:"http://linux.cn/"},{default:i(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const g=r(C,[["render",D]]);export{f as __pageData,g as default};
